// src/pages/BillDetail.js
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { billApi } from '../utils/api';
import { useApp } from '../Context/AppContext';

var statusColor = function (s) {
  if (s === 'paid')      return 'var(--emerald)';
  if (s === 'draft')     return 'var(--gold)';
  if (s === 'cancelled') return 'var(--rose)';
  return 'var(--text-3)';
};

var catColors = {
  entrance: 'var(--sky)',
  donation: 'var(--rose)',
  selling:  'var(--emerald)',
  custom:   'var(--text-3)',
};

var Row = function ({ label, value, mono, highlight }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0.5rem 0', borderBottom: '1px solid var(--border-1)' }}>
      <span style={{ fontSize: '0.82rem', color: 'var(--text-3)' }}>{label}</span>
      <span style={{
        fontFamily: mono ? 'var(--mono)' : 'var(--font)',
        fontWeight: highlight ? '800' : '600',
        color: highlight ? 'var(--orange)' : 'var(--text-1)',
        fontSize: highlight ? '1.1rem' : '0.88rem',
      }}>{value}</span>
    </div>
  );
};

var BillDetail = function () {
  var { id }   = useParams();
  var navigate = useNavigate();
  var app      = useApp();

  var [bill, setBill]       = useState(null);
  var [loading, setLoading] = useState(true);
  var [updating, setUpdating] = useState(false);

  useEffect(function () {
    billApi.getById(id)
      .then(function (res) { setBill(res.data.data); })
      .catch(function (err) {
        app.addToast(err.message, 'danger');
        navigate('/bills');
      })
      .finally(function () { setLoading(false); });
  }, [id]);

  var handleStatusChange = async function (newStatus) {
    setUpdating(true);
    try {
      var res = await billApi.setStatus(id, newStatus);
      setBill(res.data.data);
      app.addToast('Status updated to ' + newStatus, 'success');
    } catch (err) {
      app.addToast(err.message, 'danger');
    } finally {
      setUpdating(false);
    }
  };

  var handleDelete = async function () {
    if (!window.confirm('Permanently delete this bill?')) return;
    try {
      await billApi.remove(id);
      app.addToast('Bill deleted', 'success');
      navigate('/bills');
    } catch (err) {
      app.addToast(err.message, 'danger');
    }
  };

  if (loading) {
    return (
      <div className="loading-center" style={{ height: '60vh' }}>
        <span className="spinner-lg spinner" />
        <span style={{ color: 'var(--text-3)' }}>Loading bill...</span>
      </div>
    );
  }

  if (!bill) return null;

  var sc = statusColor(bill.status);

  return (
    <div>
      {/* Breadcrumb + Actions */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.5rem', flexWrap: 'wrap', gap: '0.75rem' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '6px' }}>
            <Link to="/bills" style={{ color: 'var(--text-3)', fontSize: '0.82rem' }}>All Bills</Link>
            <span style={{ color: 'var(--text-4)' }}>›</span>
            <span style={{ color: 'var(--text-2)', fontSize: '0.82rem' }}>{bill.invoiceNumber}</span>
          </div>
          <h1 style={{ fontSize: '1.4rem', fontWeight: '800' }}>
            {bill.invoiceNumber}
            <span style={{
              marginLeft: '0.75rem', fontSize: '0.7rem', padding: '3px 12px',
              borderRadius: 'var(--r-full)', background: sc + '22',
              border: '1px solid ' + sc + '44', color: sc,
              fontWeight: '700', textTransform: 'uppercase', letterSpacing: '0.1em',
              verticalAlign: 'middle',
            }}>{bill.status}</span>
          </h1>
        </div>

        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
          {bill.status !== 'paid' && (
            <button className="btn btn-success btn-sm" onClick={function () { return handleStatusChange('paid'); }} disabled={updating}>
              ✓ Mark Paid
            </button>
          )}
          {bill.status !== 'cancelled' && (
            <button className="btn btn-ghost btn-sm" onClick={function () { return handleStatusChange('cancelled'); }} disabled={updating}
              style={{ color: 'var(--rose)', borderColor: 'var(--rose)' }}>
              ✕ Cancel
            </button>
          )}
          <Link to={'/bills/' + id + '/edit'} className="btn btn-secondary btn-sm">✏️ Edit</Link>
          <button className="btn btn-ghost btn-sm" onClick={handleDelete} style={{ color: 'var(--rose)' }}>🗑 Delete</button>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 340px', gap: '1.25rem', alignItems: 'start' }}>

        {/* Left - Items */}
        <div>
          {/* Customer Info */}
          <div className="card" style={{ marginBottom: '1.25rem' }}>
            <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: '1rem' }}>
              Customer Details
            </h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: '0.75rem' }}>
              {[
                { label: 'Name',  value: bill.customerName  || '—' },
                { label: 'Email', value: bill.customerEmail || '—' },
                { label: 'Phone', value: bill.customerPhone || '—' },
              ].map(function (f) {
                return (
                  <div key={f.label}>
                    <div style={{ fontSize: '0.65rem', color: 'var(--text-4)', textTransform: 'uppercase', letterSpacing: '0.1em', fontWeight: '700', marginBottom: '3px' }}>{f.label}</div>
                    <div style={{ fontSize: '0.88rem', color: 'var(--text-1)', fontWeight: '600' }}>{f.value}</div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Items Table */}
          <div className="card" style={{ padding: 0, overflow: 'hidden', marginBottom: '1.25rem' }}>
            <div style={{ padding: '1rem 1.25rem', borderBottom: '1px solid var(--border-1)' }}>
              <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em' }}>
                Line Items ({bill.items.length})
              </h2>
            </div>
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead>
                <tr style={{ background: 'rgba(255,107,53,0.05)', borderBottom: '1px solid var(--border-1)' }}>
                  {['Item', 'Category', 'Unit Price', 'Qty', 'Total'].map(function (h) {
                    return (
                      <th key={h} style={{ padding: '0.6rem 1rem', textAlign: 'left', fontSize: '0.65rem', fontWeight: '700', color: 'var(--text-3)', textTransform: 'uppercase', letterSpacing: '0.1em' }}>
                        {h}
                      </th>
                    );
                  })}
                </tr>
              </thead>
              <tbody>
                {bill.items.map(function (item) {
                  var cc = catColors[item.category] || 'var(--text-3)';
                  return (
                    <tr key={item.id} style={{ borderBottom: '1px solid var(--border-1)' }}>
                      <td style={{ padding: '0.75rem 1rem' }}>
                        <div style={{ fontWeight: '600', fontSize: '0.88rem' }}>{item.name}</div>
                      </td>
                      <td style={{ padding: '0.75rem 1rem' }}>
                        <span style={{
                          fontSize: '0.65rem', padding: '2px 8px', borderRadius: 'var(--r-full)',
                          background: cc + '22', border: '1px solid ' + cc + '44', color: cc,
                          fontWeight: '700', textTransform: 'uppercase', letterSpacing: '0.08em',
                        }}>{item.category}</span>
                      </td>
                      <td style={{ padding: '0.75rem 1rem', fontFamily: 'var(--mono)', fontSize: '0.85rem', color: 'var(--text-2)' }}>
                        ${item.price.toFixed(2)}
                      </td>
                      <td style={{ padding: '0.75rem 1rem', fontSize: '0.85rem', color: 'var(--text-2)', textAlign: 'center' }}>
                        {item.quantity}
                      </td>
                      <td style={{ padding: '0.75rem 1rem', fontFamily: 'var(--mono)', fontWeight: '700', color: 'var(--orange)' }}>
                        ${item.total.toFixed(2)}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {/* Notes */}
          {bill.notes && (
            <div className="card">
              <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: '0.6rem' }}>
                Notes
              </h2>
              <p style={{ fontSize: '0.87rem', color: 'var(--text-2)', lineHeight: 1.6 }}>{bill.notes}</p>
            </div>
          )}
        </div>

        {/* Right - Totals */}
        <div>
          <div className="card" style={{ marginBottom: '1.25rem' }}>
            <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: '1rem' }}>
              Summary
            </h2>
            <Row label="Subtotal"   value={'$' + bill.subtotal.toFixed(2)}  mono />
            {bill.discountType !== 'none' && bill.discountAmount > 0 && (
              <div style={{ display: 'flex', justifyContent: 'space-between', padding: '0.5rem 0', borderBottom: '1px solid var(--border-1)' }}>
                <span style={{ fontSize: '0.82rem', color: 'var(--emerald)' }}>
                  Discount ({bill.discountType === 'percentage' ? bill.discountValue + '%' : 'Fixed'})
                </span>
                <span style={{ fontFamily: 'var(--mono)', fontWeight: '600', color: 'var(--emerald)', fontSize: '0.88rem' }}>
                  −${bill.discountAmount.toFixed(2)}
                </span>
              </div>
            )}
            <Row label={'Tax (' + bill.taxRate + '%)'} value={'$' + bill.taxAmount.toFixed(2)}  mono />
            <Row label="Total"      value={'$' + bill.total.toFixed(2)}     mono highlight />
          </div>

          <div className="card">
            <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: '1rem' }}>
              Bill Info
            </h2>
            <Row label="Invoice #" value={bill.invoiceNumber} />
            <Row label="Status"    value={bill.status.charAt(0).toUpperCase() + bill.status.slice(1)} />
            <Row label="Created"   value={new Date(bill.createdAt).toLocaleString()} />
            <Row label="Updated"   value={new Date(bill.updatedAt).toLocaleString()} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default BillDetail;
